#include <algorithm>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <iterator>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

static int expected(const vector<int>& a) {
    unsigned common = ~0u;
    for (int x : a) common &= static_cast<unsigned>(x);
    int count = 0;
    for (; common; common &= common - 1) ++count;
    return count;
}

static bool check(const string& exe, const vector<int>& a, int id) {
    const string inFile = "l3p1_input.txt", outFile = "l3p1_output.txt";
    {
        ofstream out(inFile);
        out << a.size() << '\n';
        for (size_t i = 0; i < a.size(); ++i) out << a[i] << (i+1 == a.size() ? '\n' : ' ');
    }
    string cmd = "\"" + exe + "\" < " + inFile + " > " + outFile + " 2>/dev/null";
    int code = system(cmd.c_str());
    ifstream out(outFile);
    string output((istreambuf_iterator<char>(out)), istreambuf_iterator<char>());
    istringstream parser(output);
    int actual = -1;
    string extra;
    const int want = expected(a);
    bool ok = code == 0 && (parser >> actual) && !(parser >> extra) && actual == want;
    if (!ok) {
        cout << "[FAIL] case " << id << ": n=" << a.size() << ", expected=" << want
             << ", actual=" << output.substr(0, 120) << ", process status=" << code << '\n';
    }
    return ok;
}

int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    vector<vector<int>> tests = {
        {13, 7, 15}, {0, 0}, {0, 1073741823}, {1, 1},
        {2, 3}, {1000000000, 1000000000}, {1000000000, 0},
        {15, 7, 3}, {1 << 29, 1 << 29}, {7, 11, 13, 15},
        {1 << 28, (1 << 28) | 15, (1 << 28) | 5},
        {0, 1, 2, 3, 4, 5}, {1023, 1023, 1023, 1023}
    };
    tests[2][1] = 1000000000;  // bound: all inputs <= 1e9
    unsigned seed = 202609u;
    for (int trial = 0; trial < 7; ++trial) {
        int n = trial == 6 ? 20000 : 2 + trial * 37;
        vector<int> a;
        for (int i = 0; i < n; ++i) {
            seed = seed * 1664525u + 1013904223u;
            a.push_back(static_cast<int>(seed % 1000000001u));
        }
        tests.push_back(a);
    }
    tests.push_back(vector<int>(20000, 1000000000));
    int pass = 0;
    for (size_t i = 0; i < tests.size(); ++i)
        if (check(argv[1], tests[i], static_cast<int>(i+1))) ++pass;
    cout << "Results: " << pass << "/" << tests.size() << " passed\n";
    return pass == static_cast<int>(tests.size()) ? 0 : 1;
}

